var d = $input.first().json;

var ga4 = d.ga4 || {};
var sc = d.searchConsole || {};
var enc = d.encharge || {};
var goji = d.gojiberry || {};

function fmt(value, change) {
  if (change && change !== 'N/A') {
    return String(value) + ' (' + change + ' vs prev week)';
  }
  return String(value);
}

var lines = [];

// ── Header ───────────────────────────────────────────────────────────────────

lines.push('CURRENT PERIOD: ' + (d.weekLabel || 'this week'));
lines.push('PREVIOUS PERIOD: ' + (d.prevLabel || 'last week'));

// ── GA4 ──────────────────────────────────────────────────────────────────────

lines.push('\n--- WEBSITE (GA4) ---');

lines.push(
  'Sessions: ' +
  fmt(ga4.totalSessions || 'N/A', ga4.sessionsChange)
);

lines.push(
  'Users: ' +
  fmt(ga4.totalUsers || 'N/A', ga4.usersChange)
);

lines.push(
  'Page Views: ' +
  fmt(ga4.totalPageViews || 'N/A', ga4.pageViewsChange)
);

lines.push(
  'Top Channels: ' +
  (ga4.topChannels || 'N/A')
);

if (ga4.error) {
  lines.push('NOTE: ' + ga4.error);
}

// ── Search Console ───────────────────────────────────────────────────────────

lines.push('\n--- SEARCH (Google Search Console) ---');

lines.push(
  'Clicks: ' +
  fmt(sc.totalClicks || 'N/A', sc.clicksChange)
);

lines.push(
  'Impressions: ' +
  fmt(sc.totalImpressions || 'N/A', sc.impressionsChange)
);

lines.push(
  'Average CTR: ' +
  (sc.avgCTR || 'N/A')
);

lines.push(
  'Average Position: ' +
  (sc.avgPosition || 'N/A')
);

lines.push(
  'Top Queries: ' +
  (sc.topQueries || 'N/A')
);

if (sc.error) {
  lines.push('NOTE: ' + sc.error);
}

// ── Encharge ─────────────────────────────────────────────────────────────────

lines.push('\n--- EMAIL (Encharge) ---');

lines.push(
  'Campaign: ' +
  (enc.campaignName || 'N/A')
);

lines.push(
  'Emails Sent: ' +
  (enc.emailsSent || 'N/A')
);

lines.push(
  'Open Rate: ' +
  (enc.openRate || 'N/A')
);

lines.push(
  'Click Rate: ' +
  (enc.clickRate || 'N/A')
);

lines.push(
  'Unsubscribes: ' +
  (enc.unsubscribes || 0)
);

if (enc.error) {
  lines.push('NOTE: ' + enc.error);
}

// ── Gojiberry ────────────────────────────────────────────────────────────────

lines.push('\n--- LINKEDIN OUTREACH (Gojiberry) ---');

lines.push(
  'New Leads Generated: ' +
  (goji.totalLeadsGenerated || 0)
);

lines.push(
  'Prospects Scanned: ' +
  (goji.totalProspectsFound || 0)
);

if (goji.bestSource) {
  lines.push(
    'Best Performing Source: ' +
    goji.bestSource.source +
    ' (' +
    goji.bestSource.leads +
    ' leads)'
  );
}

if (goji.sourceBreakdown) {
  var breakdown = Object.entries(goji.sourceBreakdown)
    .map(function(entry) {
      return entry[0] + ': ' + entry[1];
    })
    .join(', ');

  lines.push(
    'Source Breakdown: ' +
    breakdown
  );
}

if (
  goji.topKeywords &&
  Array.isArray(goji.topKeywords) &&
  goji.topKeywords.length
) {
  var keywordText = goji.topKeywords
    .map(function(k) {
      if (typeof k === 'string') {
        return k;
      }
      return (
        k.keyword +
        ' (' +
        k.leads +
        ' leads)'
      );
    })
    .join(', ');

  lines.push(
    'Top Keywords: ' +
    keywordText
  );
}

lines.push(
  'Summary: ' +
  (goji.summary || 'N/A')
);

if (goji.error) {
  lines.push('NOTE: ' + goji.error);
}

// ── Claude Instructions ──────────────────────────────────────────────────────

lines.push('\n--- TASK ---');

lines.push(
  'Write a professional weekly executive analytics digest for Droplet Lab.'
);

lines.push(
  'Use the week-over-week changes provided.'
);

lines.push(
  'Be specific about percentage increases and decreases.'
);

lines.push(
  'Identify wins, concerns, anomalies, and opportunities.'
);

lines.push(
  'Highlight important website, search, email, and lead-generation trends.'
);

lines.push(
  'For Gojiberry, discuss best-performing lead sources and top-performing keywords.'
);

lines.push(
  'Explain likely business impact, not just raw numbers.'
);

lines.push(`
Keep the tone professional, concise, and founder-friendly.
Quantify business impact wherever possible.
Do not merely restate metrics.
Explain what the numbers likely mean for Droplet Lab's growth, lead generation, and demand generation efforts.
`);

lines.push(
  'Structure the response with: Executive Summary, Wins, Concerns, Recommended Actions.'
);

// ── STRICT JSON FORMATTING ───────────────────────────────────────────────────

lines.push('\nCRITICAL: You MUST return your response ONLY as valid JSON. Do not include any markdown formatting or text outside the JSON object.');
lines.push('Use this exact JSON structure:');
lines.push('{');
lines.push('  "headline": "A catchy headline for the week",');
lines.push('  "week_label": "The date range",');
lines.push('  "ga4": { "summary": "Summary of GA4 data", "actions": ["Action 1", "Action 2"] },');
lines.push('  "search_console": { "summary": "Summary of SC data", "actions": ["Action 1"] },');
lines.push('  "email": { "summary": "Summary of Encharge data", "actions": ["Action 1"] },');
lines.push('  "outreach": { "summary": "Summary of Gojiberry data", "actions": ["Action 1"] },');
lines.push('  "top_priorities": ["Top priority 1", "Top priority 2"]');
lines.push('}');

return [
  {
    json: {
      userPrompt: lines.join('\n'),
      weekLabel: d.weekLabel
    }
  }
];

// Grab the incoming JSON payload
var data = $input.first().json;

// 1. Safely extract the text (Prioritizing the LangChain string output)
var rawText = data.text || '';
if (!rawText && typeof data.content === 'string') rawText = data.content;
if (!rawText && Array.isArray(data.content) && data.content[0]) rawText = data.content[0].text;
if (!rawText && data.output) rawText = data.output;

// If n8n automatically parsed it, stringify it so we don't break the regex
if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
}

if (!rawText) throw new Error('Anthropic node returned empty content. Check node output.');

// 2. Token usage (Handle LangChain's nested metadata locations)
var u = data.usage || data.tokenUsage || (data.response && data.response.usage) || (data.additional_kwargs && data.additional_kwargs.usage) || {};
var inputTok  = parseInt(u.input_tokens     || u.promptTokens     || u.prompt_tokens     || 0, 10);
var outputTok = parseInt(u.output_tokens    || u.completionTokens || u.completion_tokens || 0, 10);
var cacheRead = parseInt(u.cache_read_input_tokens || 0, 10);

// claude-sonnet-4-6 pricing: $3/M input, $15/M output
var costRun   = ((inputTok * 3) + (outputTok * 15)) / 1000000;
var tokenLog  = 'Input: '+inputTok+' | Output: '+outputTok+
                (cacheRead ? ' | Cache read: '+cacheRead : '')+
                ' | Run cost: $'+costRun.toFixed(5)+
                ' | Monthly est. (4 runs): $'+(costRun*4).toFixed(4);

// 3. Parse Claude's JSON
var brief;
try {
  var cleaned = rawText.trim().replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim();
  brief = JSON.parse(cleaned);
} catch(e) {
  return [{ json: {
    parseError:   true,
    tokenLog:     tokenLog,
    emailSubject: '\u26a0\ufe0f Weekly Brief \u2014 Parse Error (manual review needed)',
    emailHtml:    '<p>Claude response could not be parsed as JSON.</p><pre>'+rawText+'</pre><hr><small>'+tokenLog+'</small>'
  }}];
}

// 4. HTML helpers
function toUl(arr) {
  if (!arr||!arr.length) return '';
  return '<ul style="margin:6px 0 0 0;padding-left:18px;">'+
    arr.map(function(a){return '<li style="color:#444;font-size:13px;margin-bottom:3px;">'+a+'</li>';}).join('')+
    '</ul>';
}
function section(emoji, title, s) {
  s = s || {};
  return '<div style="margin-bottom:18px;padding:14px 16px;background:#f9f9f9;'+
    'border-left:3px solid #2d6a4f;border-radius:4px;">'+
    '<div style="font-weight:700;font-size:13px;margin-bottom:6px;color:#1a1a1a;letter-spacing:.3px;">'+emoji+' '+title.toUpperCase()+'</div>'+
    '<div style="font-size:13px;color:#333;line-height:1.65;">'+(s.summary||'No data available.')+'</div>'+
    toUl(s.actions)+'</div>';
}

var today = new Date().toLocaleDateString('en-GB',{weekday:'long',year:'numeric',month:'long',day:'numeric'});

var html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:28px 24px;color:#1a1a1a;background:#fff;">',
  // Header banner
  '<div style="background:#1a3d2b;color:#fff;padding:18px 20px;border-radius:6px;margin-bottom:22px;">',
  '<div style="font-size:10px;opacity:.7;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:4px;">Droplet Lab \u2014 Weekly Performance Brief</div>',
  '<div style="font-size:19px;font-weight:700;line-height:1.3;">'+(brief.headline||'Weekly Summary')+'</div>',
  '<div style="font-size:12px;opacity:.75;margin-top:6px;">'+(brief.week_label||'')+' &bull; '+today+'</div>',
  '</div>',
  // Sections
  section('\ud83d\udcca','Website Traffic (GA4)',     brief.ga4),
  section('\ud83d\udd0d','Search Performance',         brief.search_console),
  section('\ud83d\udce7','Email (Encharge)',           brief.email),
  section('\ud83e\udd1d','LinkedIn Outreach (Gojiberry)',brief.outreach),
  // Top priorities
  '<div style="padding:14px 16px;background:#fffbeb;border-left:3px solid #d97706;border-radius:4px;margin-bottom:20px;">',
  '<div style="font-weight:700;font-size:13px;margin-bottom:8px;color:#1a1a1a;letter-spacing:.3px;">\ud83c\udfaf TOP PRIORITIES THIS WEEK</div>',
  toUl(brief.top_priorities),
  '</div>',
  // Token usage footer
  '<div style="font-size:10px;color:#999;border-top:1px solid #ebebeb;padding-top:10px;margin-top:4px;">',
  '<strong style="color:#777;">Token usage this run:</strong> '+tokenLog,
  '</div>',
  '</body></html>'
].join('');

return [{ json: {
  emailSubject: '\ud83d\udcca Weekly Brief \u2014 '+(brief.week_label||'This Week')+' | '+(brief.headline||'Droplet Lab'),
  emailHtml:    html,
  tokenLog:     tokenLog,
  brief:        brief
}}];

let leadsCreated = 0;
let prospectsFound = 0;

const sources = {};
const keywords = {};

for (const item of $input.all()) {

  leadsCreated += item.json.leadsCreated || 0;
  prospectsFound += item.json.totalLeads || 0;

  const type = item.json.agentType || "Unknown";

  // Source breakdown
  sources[type] = (sources[type] || 0)
    + (item.json.leadsCreated || 0);

  // Keyword tracking
  const keyword = item.json.agentKeyword;

  if (keyword) {
    keywords[keyword] =
      (keywords[keyword] || 0)
      + (item.json.leadsCreated || 0);
  }
}

// Top 5 keywords as structured JSON
const topKeywords = Object.entries(keywords)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([keyword, leads]) => ({
    keyword,
    leads
  }));

// Best performing source
const bestSource = Object.entries(sources)
  .sort((a, b) => b[1] - a[1])[0];

return [{
  json: {

    total_leads_generated: leadsCreated,

    total_prospects_found: prospectsFound,

    source_breakdown: sources,

    top_keywords: topKeywords,

    best_source: bestSource
      ? {
          source: bestSource[0],
          leads: bestSource[1]
        }
      : null,

    gojiberry_summary:
      `Generated ${leadsCreated} new leads from ${prospectsFound} prospects scanned.`

  }
}];

// ── Helpers ──────────────────────────────────────────────────────────────────
function calcChange(curr, prev) {
  curr = parseFloat(curr) || 0;
  prev = parseFloat(prev) || 0;
  if (prev === 0) return 'N/A';
  var pct = ((curr - prev) / prev * 100).toFixed(1);
  return (parseFloat(pct) >= 0 ? '↑' : '↓') + Math.abs(parseFloat(pct)) + '%';
}

function aggregateGA4(nodeName) {
  var items = $(nodeName).all();

  var sessions = 0;
  var users = 0;
  var pageViews = 0;
  var channels = {};

  items.forEach(function(item) {
    var d = item.json;

    var s = parseInt(d.sessions || 0, 10);
    var u = parseInt(d.totalUsers || d.activeUsers || 0, 10);
    var p = parseInt(d.screenPageViews || d.pageViews || 0, 10);

    var ch = d.sessionDefaultChannelGroup || 'Unknown';

    sessions += s;
    users += u;
    pageViews += p;

    channels[ch] = (channels[ch] || 0) + s;
  });

  var topCh = Object.entries(channels)
    .sort(function(a, b) { return b[1] - a[1]; })
    .slice(0, 3)
    .map(function(e) {
      return e[0] + ': ' + e[1] + ' sessions';
    })
    .join(', ');

  return {
    sessions: sessions,
    users: users,
    pageViews: pageViews,
    topChannels: topCh
  };
}

function aggregateSC(nodeName) {

  var items = $(nodeName).all();
  var rows = [];

  if (items.length === 1 && items[0].json && items[0].json.rows) {
    rows = items[0].json.rows;
  } else {
    rows = items.map(function(item) {
      return item.json;
    });
  }

  var clicks = 0;
  var impressions = 0;
  var ctrSum = 0;
  var posSum = 0;

  rows.forEach(function(row) {
    clicks += row.clicks || 0;
    impressions += row.impressions || 0;
    ctrSum += row.ctr || 0;
    posSum += row.position || 0;
  });

  return {
    clicks: clicks,
    impressions: impressions,
    avgCTR: rows.length
      ? (ctrSum / rows.length * 100).toFixed(1) + '%'
      : 'N/A',
    avgPos: rows.length
      ? (posSum / rows.length).toFixed(1)
      : 'N/A',
    topQueries: rows
      .sort(function(a, b) {
        return b.clicks - a.clicks;
      })
      .slice(0, 5)
      .map(function(r) {
        return '"' +
          (r.keys ? r.keys[0] : (r.query || '?')) +
          '" (' + r.clicks + ' clicks)';
      })
      .join(', ')
  };
}

var ga4Data;
var searchData;
var enchargeData;
var gojiberryData;

// ── GA4 ──────────────────────────────────────────────────────────────────────
try {

  var g = aggregateGA4('GA4 — Last 7 Days');
  var gp = aggregateGA4('GA4 — Previous 7 Days');

  ga4Data = {
    totalSessions: g.sessions,
    totalUsers: g.users,
    totalPageViews: g.pageViews,
    topChannels: g.topChannels,
    sessionsChange: calcChange(g.sessions, gp.sessions),
    usersChange: calcChange(g.users, gp.users),
    pageViewsChange: calcChange(g.pageViews, gp.pageViews)
  };

} catch(e) {

  ga4Data = {
    error: 'GA4 unavailable: ' + e.message
  };

}

// ── Search Console ───────────────────────────────────────────────────────────
try {

  var s = aggregateSC('Search Console — Last 7 Days');
  var sp = aggregateSC('Search Console — Previous 7 Days');

  searchData = {
    totalClicks: s.clicks,
    totalImpressions: s.impressions,
    avgCTR: s.avgCTR,
    avgPosition: s.avgPos,
    topQueries: s.topQueries,
    clicksChange: calcChange(s.clicks, sp.clicks),
    impressionsChange: calcChange(s.impressions, sp.impressions)
  };

} catch(e) {

  searchData = {
    error: 'Search Console unavailable: ' + e.message
  };

}

// ── Encharge ─────────────────────────────────────────────────────────────────
try {

  var encItems = $('Encharge — Recent Broadcasts').all();

  var b = encItems[0]
    ? encItems[0].json
    : {};

  var latestBroadcast =
    (b.broadcasts && b.broadcasts.length > 0)
      ? b.broadcasts[0]
      : {};

  var stats = latestBroadcast.stats || {};

  enchargeData = {
    emailsSent: stats.sent || 'N/A',
    openRate: stats.openRate
      ? stats.openRate + '%'
      : 'N/A',
    clickRate: stats.clickRate
      ? stats.clickRate + '%'
      : 'N/A',
    unsubscribes: stats.unsubscribes || 0,
    campaignName:
      latestBroadcast.name ||
      latestBroadcast.subject ||
      'No recent broadcasts'
  };

} catch(e) {

  enchargeData = {
    error: 'Encharge unavailable: ' + e.message
  };

}

// ── Gojiberry ────────────────────────────────────────────────────────────────
try {

  var g2 = $('Gojiberry — Parse Leads').first().json;

  gojiberryData = {
    totalLeadsGenerated: g2.total_leads_generated || 0,
    totalProspectsFound: g2.total_prospects_found || 0,
    sourceBreakdown: g2.source_breakdown || {},
    topKeywords: g2.top_keywords || [],
    bestSource: g2.best_source || null,
    summary: g2.gojiberry_summary || 'N/A'
  };

} catch(e) {

  gojiberryData = {
    error: 'Gojiberry unavailable: ' + e.message
  };

}

var weekLabel =
  $now.minus({days: 7}).toFormat('MMM d') +
  ' – ' +
  $now.minus({days: 1}).toFormat('MMM d, yyyy');

var prevLabel =
  $now.minus({days: 14}).toFormat('MMM d') +
  ' – ' +
  $now.minus({days: 8}).toFormat('MMM d, yyyy');

return [{
  json: {
    weekLabel: weekLabel,
    prevLabel: prevLabel,
    ga4: ga4Data,
    searchConsole: searchData,
    encharge: enchargeData,
    gojiberry: gojiberryData,
    collectedAt: $now.toISO()
  }
}];
